 Following example illustrate the implementation of Aggregate. 

 string function;
 //setting current aggregator function

 public IntAggregator(string function)
 {
    this.function = function;
 }

 //Implementing interface function

 public object Aggregate(object value)
 {
    return calculate(value);
 }
 //Function to calculate values

 private object calculate(object value)
 {
    switch (function)
    {
        case "MIN":
            value = int.MinValue;
            return value;
        case "MAX":
            value = int.MaxValue;
            return value;
        default:
            return 0;
    }
}

 Following example illustrate the implementation of Aggregate. 

 string function;
 //setting current aggregator function

 public IntAggregator(string function)
 {
    this.function = function;
 }

 //Implementing interface function

 public object AggregateAll(object value)
 {
    return calculate(value); //implement inside logic.
 }
 //Function to calculate values

 private object calculate(object value)
 {
    switch (function)
    {
        case "MIN":
            value = int.MinValue;
            return value;
        case "MAX":
            value = int.MaxValue;
            return value;
        default:
            return 0;
    }
}

Following example demonstrates the implementation of Extract. 

public object Extract(object value)
{
   try
   {
      if (value.GetType() == typeof(int))
       {
           return 0;
       }
      if (value.GetType() == typeof(float))
       {
           return 0.0;
       }
   }
   catch (Exception e)
   {
      //handle exception
   }
   return value;
}

