Performs a single operation on data source

public ProviderCacheItem LoadFromSource(string key, ProviderCacheItem cacheItem)
{	
	return new ProviderCacheItem(_source.LoadCustomer(key));
}

Example performs multiple operations on data source

public Dictionary<string, > LoadFromSource(string[] keys)
{
    Dictionary<string", > pciDict = new Dictionary<string, >();
    foreach (string key in keys)
    {
         item = null;
        LoadFromSource(key, out item);
        pciDict.Add(key, item);
    }
    return pciDict;
}

